// Approved design turns only. Regeneration never edits application code or private specs.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const here = path.dirname(fileURLToPath(import.meta.url));
const css = fs.readFileSync(path.join(here, 'editor-effects-213.css'), 'utf8');
const esc = value => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const button = (label, act='', cls='', extra='') => `<button type="button" class="${cls}" ${act ? `data-act="${act}"` : ''} ${extra}>${label}</button>`;
const field = (label, body) => `<label class="field"><span>${label}</span>${body}</label>`;
const select = (label, options, chosen, key='') => field(label, `<select aria-label="${label}" ${key?`data-key="${key}"`:''}>${options.map(o=>`<option ${o===chosen?'selected':''}>${o}</option>`).join('')}</select>`);
const slider = (label, value, key='', max=100) => field(label, `<span class="slider-line"><input type="range" aria-label="${label}" min="0" max="${max}" value="${value}" ${key?`data-key="${key}"`:''}><output>${value}%</output></span>`);
const toggle = (label, on=true, act='') => button(`<span>${label}</span><span class="row"><b>${on?'On':'Off'}</b><i aria-hidden="true"></i></span>`,act,`switch ${on?'':'off'}`,`role="switch" aria-label="${label}" aria-checked="${on}"`);
const section = body => `<div class="section">${body}</div>`;
const visualTargets=['Whole composition','Video track · Video 1','Visual clip · Still 2'];
const audioSources=['Choose audio…','Composition audio mix','Audio track · Audio 1','Audio clip · Harbour lights.wav','Video sound · Harbour boat.mp4'];
const timeFields=(start='0:00',end='3:12',prefix='')=>`<div class="inline-form">${field('Start',`<input type="text" value="${start}" aria-label="${prefix}Start" data-key="start">`)}${field('End',`<input type="text" value="${end}" aria-label="${prefix}End" data-key="end">`)}</div>`;
const placementFields=(o={})=>`${select('Visual target',visualTargets,o.visualTarget||'Whole composition','visualTarget')}${timeFields(o.start,o.end)}<p class="meta">Target and time are independent. Clip targets appear only while that clip is visible.</p>`;
const reviewBack=o=>o.review&&!o.applied?button('‹ Back to proposal','changes','ghost'):'';
const protectedProperty=(key,label,checked=false)=>`<label class="protect-property"><input type="checkbox" data-protect="${key}" ${checked?'checked':''}>${label}</label>`;
const notice = (title, text='', warning=false) => `<div class="notice ${warning?'warning':''}"><b>${title}</b>${text?`<span>${text}</span>`:''}</div>`;
const dots = (count=20, ember=false) => Array.from({length:count},(_,i)=>`<i class="${ember?'particle ember':'particle'}" style="left:${(i*47+11)%96}%;top:${(i*29+13)%92}%;width:${2+i%3}px;height:${2+i%3}px;opacity:${.25+(i%5)*.13}"></i>`).join('');
const sample = name => `<span class="sample ${name}">${Array.from({length:15},(_,i)=>`<i style="left:${(i*37+9)%95}%;top:${(i*23+5)%91}%"></i>`).join('')}</span>`;
const presets = () => `<div class="presets">${[['dust','Floating dust'],['embers','Embers'],['snow','Snow'],['lights','Floating lights'],['rain','Rain'],['smoke','Smoke']].map(([key,title])=>button(`${sample(key)}<span>${title}</span>`,`preset-${key}`,`preset ${key==='dust'?'on':''}`)).join('')}</div>`;
function library(){return `<aside class="library"><div class="row between"><h3>Library</h3>${button('＋','','ghost','aria-label="Import media"')}</div><div class="tabs">${button('Media')}${button('Effects','','on')}</div><input class="search" aria-label="Search effects" placeholder="Search effects"><div class="row between"><span class="eyebrow">Atmosphere</span><span class="meta">6 presets</span></div>${presets()}${button('Add effect','place','primary full')}${button('Suggest arrangement','suggest','full')}<p class="meta" style="margin-top:12px">Choose a preset, then its place on the timeline.</p></aside>`;}
function curve(kind='Intensity', live=false){const pts=kind==='Intensity'?[[0,54],[90,45],[210,45],[320,12],[390,12],[490,45],[590,57]]:[[0,57],[90,51],[210,51],[320,25],[390,25],[490,51],[590,60]];return `<svg class="curve" viewBox="0 0 600 72" preserveAspectRatio="none" aria-label="${kind} curve" ${live?'data-live-curve="true"':''}><path d="M0 60H600M0 36H600M0 12H600" fill="none" stroke="var(--border)"/><path class="response" d="M0 60L20 54 25 22 30 54 50 57 60 34 65 54 95 57 100 25 105 54 150 55 155 40 160 55 210 52 215 25 220 52 255 48 260 16 265 45 310 32 315 10 320 33 350 24 355 5 360 25 400 36 405 16 410 37 460 48 465 28 470 49 520 55 525 40 530 55 590 60"/><polyline class="base" points="${pts.map(p=>p.join(',')).join(' ')}"/>${pts.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" ${live?`tabindex="0" role="slider" aria-label="Curve point ${i+1}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round((60-y)/.48)}" data-point="${i}"`:''}/>`).join('')}</svg>`;}
function timeline(o={}){
 const review=o.review&&!o.applied&&!o.current;
 const currentProposal=o.current&&o.panel==='chat';
 const pictures=['launch-harbour.webp','launch-plate.webp','saltlight-shot15.png','launch-harbour.webp','launch-plate.webp'].map((src,i)=>`<div class="picture-clip"><img src="assets/${src}" alt=""><span>${i===2?'Harbour boat.mp4 · 8 s · ♫':`Still ${i+1}`}</span></div>`).join('');
 return `<div class="timeline">
 <div class="tl-tools"><b class="grow">Timeline</b>${button('＋ Effect','place')}${button('Curves','curves')}${button('Snap','','ghost')}<span class="meta desktop-only">− &nbsp; 60% &nbsp; ＋</span></div>
 <div class="ruler"><span>0:00</span><span>0:48</span><span>1:36</span><span>2:24</span><span>3:12</span></div>
 <div class="lane"><div class="lane-label"><span class="grow">Dust</span>${button('◉','hide','ghost','aria-label="Hide dust"')}</div><div class="lane-content"><div class="effect-block selected ${review?'proposed':''}" style="left:2%;width:96%" data-effect="dust">Floating dust ${review?'· Changed':o.panel==='placement'?'· Video 1':o.off||!['response','advanced','curves','sources'].includes(o.panel)?'· Atmosphere':'· Audio 1'} ${o.protected?'· Protected':''}</div></div></div>
 <div class="lane"><div class="lane-label"><span class="grow">${currentProposal?'Effects':'Embers'}</span></div><div class="lane-content"><div class="effect-block ${review?'proposed':''}" style="left:43%;width:24%" data-effect="embers" ${currentProposal?'hidden':''}>Embers ${review?'· Added':'· Beat pulse'}</div>${review?'<div class="effect-block removed" data-effect="leak" style="left:74%;width:23%">Light leak · Removed</div>':currentProposal?'<div class="effect-block" data-effect="leak" style="left:74%;width:23%">Light leak</div>':''}</div></div>
 ${o.curves?`<div class="curve-row"><div class="row between"><b class="small" data-curve-label>Intensity</b><div class="segmented">${button('Intensity','curve-intensity','on')}${button('Audio reaction','curve-reaction')}</div></div>${curve('Intensity',o.live)}</div>`:''}
 <div class="lane"><div class="lane-label">Video 1</div><div class="lane-content"><div class="clip-strip">${pictures}</div></div></div>
 <div class="lane"><div class="lane-label">Audio 1</div><div class="lane-content"><div class="wave">${Array.from({length:170},(_,i)=>`<i style="height:${6+(i*17%29)}px"></i>`).join('')}</div><span class="song-label">Harbour lights.wav</span></div></div>
 <div class="playhead" data-playhead></div></div>`;
}
function appearance(o={}){return `${reviewBack(o)}${section(`<div class="row between"><div><div class="eyebrow">Effect</div><h2>Floating dust</h2></div><span class="tag">${o.review?'Changed':'Selected'}</span></div><p class="meta" data-placement-summary>Whole composition · 0:00–3:12</p><div class="row wrap">${button('Edit placement','placement-settings')}${button('Audio reaction','response')}</div><p class="meta" data-audio-summary>${o.review?'Audio 1 · Gentle shimmer':'Audio reaction off'}</p>`)}${o.review?section(`<div class="row between"><b class="small">Your review adjustment</b>${button('Keep current','keep-current','','aria-label="Keep current dust"')}</div><p class="meta">Amount: 35% → <b data-amount-change>${o.adjusted?'24':'42'}%</b></p>`):''}${section(`<h3>Appearance</h3>${slider('Amount',o.adjusted?24:42,'amount')}${slider('Particle size',24,'size')}${slider('Opacity',60,'opacity')}<div class="row between"><span class="small">Colour</span><span class="row"><i class="swatch"></i><span class="small">Warm ivory</span>${button('Edit')}</span></div>`)}${section(`<h3>Motion</h3>${select('Direction',['Upwards','Downwards','Drift'],'Drift')}${slider('Speed',18,'speed')}${select('Coverage',['Full frame','Emitting area'],'Full frame')}<div class="inline-form">${field('Fade in','<input type="text" value="4 s" aria-label="Fade in">')}${field('Fade out','<input type="text" value="8 s" aria-label="Fade out">')}</div>`)}${section(`<div class="row between"><h3>Protected settings</h3><span class="tag" data-protection-count>${o.protected?'3 settings':'Colour'}</span></div><p class="meta" data-protection-summary>Colour · whole effect${o.protected?'<br>Visual target and timing · whole effect':''}</p>${button('Manage protection','protect-settings')}${button('Ask Arke about this effect','ask')}`)}`;}
function placementPanel(o={}){return `${reviewBack(o)}${section('<div class="eyebrow">Floating dust</div><h2>Placement</h2>')}${section(placementFields({...o,visualTarget:o.visualTarget||'Video track · Video 1'}))}${section(`<h3>Audio reaction · optional</h3><p class="meta" data-placement-audio>${o.off?'Off · atmosphere continues':'Video sound · Harbour boat.mp4<br>Video 1 · source placement 1:36–1:44'}</p>${button('Edit audio reaction','response')}<p class="meta">The audio source does not select the visual target or change this interval.</p>`)}${section(`<h3>Protected settings</h3><p class="meta">Colour · Whole effect</p>${button('Manage protection','protect-settings')}`)}`;}
function response(o={}){return `${reviewBack(o)}${section(`<div class="eyebrow">Floating dust</div><h2>Audio reaction</h2><p class="meta" data-placement-summary>Whole composition · 0:00–3:12</p>${button('Edit placement','placement-settings')}`)}${section(`${toggle('React to audio',!o.off,'react')}<div data-audio-controls ${o.off?'hidden':''}>${select('Audio source',audioSources,o.source||'Audio track · Audio 1','audioSource')}${button('Browse audio sources','sources','full')}${o.missing?notice('Source needs attention','Harbour lights.wav on Audio 1 changed. Rebind and review the response.',true):`<p class="meta" data-source-status>${o.source==='Composition audio mix'?'Mix follows timeline mute and levels':'Ready · source follows Audio 1 placement'}</p>`}</div><div data-atmosphere-note ${o.off?'':'hidden'}>${notice('Atmosphere stays on','No audio source is required. Appearance, motion, intensity and fades still apply.')}</div>`)}${!o.off?`<div data-reaction-settings>${section(`${select('Response preset',['Gentle shimmer','Beat pulse','Build with energy','Custom'],'Gentle shimmer','response')}${slider('Reaction strength',30,'strength')}${slider('Base atmosphere',35,'amount')}<p class="meta">Outside the source interval or during silence, the base atmosphere remains.</p>`)}</div>`:''}${!o.off?`<div data-reaction-settings>${section(`${button(`${o.advanced?'⌄':'›'} Advanced`,'advanced','ghost','aria-expanded="'+!!o.advanced+'"')}<div class="advanced-section" ${o.advanced?'':'hidden'}>${slider('Beat',60,'beat')}${slider('Bass',20,'bass')}${slider('Energy',35,'energy')}${select('Changes',['Brightness','Emission','Size','Speed'],'Brightness','target')}${slider('Response limit',65,'limit')}${select('Smoothing',['Soft swells','Balanced','Sharp pulses'],'Soft swells','smoothing')}<p class="meta">Edited preset · Custom</p></div>`)}</div>`:''}${!o.off?`<div data-reaction-settings>${section(`<h3>Audio cues</h3><p class="meta">Likely beat · 1:36.00</p><div class="row">${button('Add accent','accent')}${button('Edit cues','cues')}</div><p class="meta">Section names are suggestions. Move boundaries or rename them.</p>`)}</div>`:''}`;}
function sourcePanel(){return `${section('<div class="eyebrow">Floating dust · Audio reaction</div><h2>Choose audio source</h2><p class="meta" data-placement-summary>Target: Whole composition<br>Effect time: 0:00–3:12</p>')}${section(`<p class="meta">Choose explicitly. No track is required to be music.</p>${audioSources.slice(1).map((name,i)=>button(`<i class="radio"></i><span class="grow"><b>${name}</b><br><span class="meta">${['Audible timeline · mute and levels apply','Audio 1 · placed clips on this track','Audio 1 · 0:00–3:12','Video 1 · 1:36–1:44 · includes sound'][i]}</span></span>`,`source-${i+1}`,`choice ${i===1?'on':''}`,`data-source="${name}"`)).join('')}${button('Still 2 · no audio','','choice','disabled')}`)}${section(`<p class="meta">Clip/track signals follow their timeline placement and audio levels. Silence leaves the base atmosphere. Choosing a source keeps visual placement intact.</p>${button('‹ Back to audio reaction','response')}`)}`;}
function changes(o={}){const inactive=!o.review||o.stale||o.refine;return `<div class="composite-changes" data-card-changes><details class="card-effect" ${o.details?'open':''}><summary><b>Floating dust</b><span class="tag">Changed</span></summary><div class="change"><span class="range" data-placement-summary>Whole composition · 0:00–3:12</span><span class="small">Amount <span class="old">35%</span> → <b data-amount-change>${o.adjusted?'24':'42'}%</b></span><span class="meta" data-audio-summary>Audio 1 · Gentle shimmer</span><div class="row wrap">${button('Inspect effect','inspect-dust','',inactive?'disabled':'')}${button('Keep current','keep-current','',inactive?'disabled':'')}</div></div></details><details class="card-effect"><summary><b>Embers</b><span class="tag">Added</span></summary><div class="change"><span class="range">Video 1 · 1:20–2:08</span><span class="meta">Audio 1 · Beat pulse · fades 3 s / 6 s</span>${button('Exclude effect','exclude','',inactive?'disabled':'')}</div></details><details class="card-effect"><summary><b>Light leak</b><span class="tag">Removed</span></summary><div class="change"><span class="range">Whole composition · 2:24–3:12</span><span class="meta">Audio reaction off</span>${button('Keep current','keep-leak','',inactive?'disabled':'')}</div></details></div>`;}
function compositeCard(o={}){const version=o.refine?2:1;return `<article class="chat-card composite-card" data-proposal-card data-card-role="${o.refine?'incoming':'active'}"><div class="row between wrap"><b>Effect arrangement</b><span class="tag" data-card-version>Version ${version}</span></div><span class="tag" data-card-status>${o.applied?'Applied':o.stale?'Needs updating':o.refine?'Ready · not previewing':o.review?'Reviewing':'Ready · not previewing'}</span><p class="meta" data-card-scope>Whole composition · 0:00–3:12<br>Audio 1 · optional reaction</p><p class="meta" data-card-adjustments>${o.adjusted?'Adjusted by you · amount 24%':'1 changed · 1 added · 1 removed'}</p><div class="card-preserved"><b class="small">Protected settings preserved</b><p class="meta" data-card-protection>Dust colour · whole effect<br>Dust timing · opening 0:00–0:24</p></div><details class="proposal-details" ${o.details?'open':''}><summary><span data-card-count>3 changes</span> · view details</summary>${changes(o)}</details>${o.applied?button('Undo arrangement','undo'):o.stale?`${notice('Current timeline changed','Update the proposal, then choose Review in timeline again.',true)}${button('Update proposal','update','primary')}`:`${button(o.refine?'Review version 2':'Review in timeline',o.refine?'review-new':'review','primary','data-card-review')}${o.review&&!o.refine?`<p class="meta" data-card-preview>Reviewing Version 1 · ${o.current?'Current':'Suggested'}</p>`:`<p class="meta">${o.refine?'Version 1 preview':'Current preview'} stays active until you choose to review.</p>`}`}</article>`; }
function conversation(o={}){return `${o.compact?'':section('<div class="eyebrow">Arke · Effects</div><h2>Harbour lights</h2>')}<p class="chat-message" ${o.compact?'hidden':''}>${o.generating?'I’m preparing an effect arrangement for the chosen target, range and audio source.':o.refine?'Version 2 is ready. I kept your amount, target, audio source and protected settings. Version 1 remains in your preview until you choose Review version 2.':o.applied?'Your reviewed effect arrangement was applied as one undoable edit.':'I suggest dust over the composition and embers on Video 1 during the build, reacting to Audio 1. Your protected timing and colour stay as chosen.'}</p>${o.generating?notice('Preparing suggestion','Current timeline and preview remain active.'):compositeCard(o)}${o.refine?'<details class="retained-card"><summary>Version 1 · Adjusted by you · still reviewing</summary>'+compositeCard({...o,refine:false,details:true})+'</details>':''}<div class="composer"><span class="tag">${o.refine?'Selected · 1:20–1:45':o.review?'Floating dust · 0:00–3:12':'Cut · Effects'}</span><textarea aria-label="Ask Arke to revise the arrangement" placeholder="Ask for changes…">${o.refine?'Make this less busy. Keep my dust adjustments.':''}</textarea><div class="row between"><span class="meta">＋ &nbsp; Default model</span>${button('Send','send','primary')}</div></div>`;}
function curvesPanel(){return `${section('<div class="eyebrow">Floating dust</div><h2>Intensity curve</h2>')}${section(`<p class="small">Selected point · 1:36</p><div class="inline-form">${field('Time','<input type="text" value="1:36.00" aria-label="Point time">')}${field('Intensity','<input type="number" value="80" aria-label="Point intensity">')}</div>${select('Between points',['Smooth','Linear','Hold'],'Smooth')}<div class="row">${button('Add point','point')}${button('Delete point')}</div>`)}${section(`<h3>Audio reaction curve</h3>${curve('Audio reaction')}<p class="meta">Steady atmosphere can have gentle reaction. Each curve has its own points.</p>`)}${section(`${toggle('Preview audio reaction',true,'preview-react')}${button('Loop selection','loop')}<p class="meta">1:20–2:08 · fades remain the final visibility control</p>`)}`;}
function reviewBar(o={}){return `<div class="review-bar"><div class="review-status grow"><b data-review-title>${o.stale?'Review needs updating':o.applied?'Arrangement applied':'Reviewing suggestion'}</b><div class="meta" data-review-meta>${o.applied?'One undoable edit':o.stale?'Timeline changed · your adjustments retained':`Version 1 · ${o.adjusted?'Adjusted by you · ':''}0:00–3:12`}</div></div>${o.applied?button('Undo arrangement','undo'):`${button('3 changes','changes','','data-change-count aria-label="Review arrangement changes"')}<div class="segmented" role="group" aria-label="Compare arrangement">${button('Current','current',o.current?'on':'')}${button('Suggested','suggested',o.current?'':'on')}</div><div class="row bar-actions">${button('Discard','discard')}${button(o.stale?'Update proposal':'Apply reviewed version',o.stale?'update':'apply','primary')}</div>`}</div>`;}
function placement(o={}){return `<div class="overlay"><div class="dialog" role="dialog" aria-label="Add Floating dust"><div class="row between"><h2>Add Floating dust</h2>${button('✕','cancel','ghost','aria-label="Close placement"')}</div>${select('Visual target',visualTargets,'Whole composition','addVisualTarget')}${select('Time range',['Whole video · 0:00–3:12','Selected range · 1:20–2:08','Selected picture · 0:48–1:20'],'Whole video · 0:00–3:12','addRange')}${timeFields('0:00','3:12','Effect ')}<p class="meta">An independent interval. Whole video uses its current duration; changing duration is a separate edit.</p>${notice('Audio reaction off','No audio source is needed. Add a response later in Inspector.')}<div class="row between">${button('Cancel','cancel')}${button('Add to timeline','add','primary')}</div></div></div>`;}
function suggestDialog(){return `<div class="overlay"><div class="dialog" role="dialog" aria-label="Suggest effect arrangement"><div class="row between"><h2>Suggest effect arrangement</h2>${button('✕','cancel','ghost','aria-label="Close suggestion"')}</div>${select('Visual target',visualTargets,'Whole composition','suggestVisualTarget')}${select('Time range',['Whole video · 0:00–3:12','Selected range · 1:20–2:08'],'Whole video · 0:00–3:12','suggestRange')}${select('Audio reaction',['Off · no audio source',...audioSources.slice(1)],'Audio track · Audio 1','suggestAudioSource')}${field('Creative direction','<textarea rows="2" class="direction-input" aria-label="Creative direction">Subtle and dreamy. Build with the chosen audio.</textarea>')}${select('Effect palette',['Dust and embers','Floating lights','Choose effects…'],'Dust and embers')}<p class="meta">Protected: dust colour (whole effect) and timing (0:00–0:24). Arke must preserve these.</p><div class="row between">${button('Cancel','cancel')}${button('Prepare suggestion','prepare','primary')}</div></div></div>`;}
function protectPanel(){return `${section('<div class="eyebrow">Floating dust</div><h2>Protect from suggestions</h2>')}${section(`${select('Protection range',['Whole effect','Selected range'],'Selected range','protectionRange')}${field('Selected passage','<input type="text" value="0:00–0:24" aria-label="Protected range" data-key="protectedPassage">')}<p class="meta">Choose individual settings. A protected colour leaves amount and reaction editable.</p><div class="protection-group"><h3>Placement</h3>${protectedProperty('visualTarget','Visual target')}${protectedProperty('start','Start',true)}${protectedProperty('end','End',true)}</div><div class="protection-group"><h3>Appearance</h3>${protectedProperty('colour','Colour')}${protectedProperty('amount','Amount')}${protectedProperty('size','Particle size')}${protectedProperty('opacity','Opacity')}</div><details class="protection-details"><summary>Motion, curves and audio · 17 settings</summary><div class="protection-group">${[['direction','Direction'],['speed','Speed'],['coverage','Emitting area'],['fadeIn','Fade in'],['fadeOut','Fade out'],['points','Intensity curve'],['audioSource','Audio source'],['react','Reaction on/off'],['response','Response preset'],['beat','Beat'],['bass','Bass'],['energy','Energy'],['target','Affected property'],['limit','Response limit'],['smoothing','Smoothing'],['strength','Reaction strength'],['reactionPoints','Reaction curve']].map(([key,label])=>protectedProperty(key,label)).join('')}</div></details><div class="notice"><b>Selection to protect</b><span data-protection-selection>Start and end · selected passage 0:00–0:24</span></div>${button('Protect selected settings','save-protection','primary')}<p class="meta">Direct edits stay available. Protection constrains AI suggestions until you release it.</p>`)}${section('<h3>Already protected</h3><div data-current-protection><div class="protection-entry"><span class="meta">Colour · whole effect</span>'+button('Release colour','release-protection','','data-protection-index="0"')+'</div></div>')}`;}
function audioProtectionPanel(){return `${section('<div class="eyebrow">Floating dust · Protection</div><h2>Audio settings</h2><p class="meta">Protection range · Whole effect</p>')}${section(`<h3>Audio reaction</h3>${[['audioSource','Audio source'],['react','Reaction on/off'],['response','Response preset'],['strength','Reaction strength'],['reactionPoints','Reaction curve']].map(([key,label])=>protectedProperty(key,label,['audioSource','strength'].includes(key))).join('')}`)}${section(`<h3>Advanced · individual settings</h3>${[['beat','Beat'],['bass','Bass'],['energy','Energy'],['target','Affected property'],['limit','Response limit'],['smoothing','Smoothing']].map(([key,label])=>protectedProperty(key,label)).join('')}`)}${section(`${notice('Selection to protect','Audio source and reaction strength · Whole effect')}${button('Protect selected settings','save-protection','primary')}<p class="meta">Keep the chosen source and strength. Arke can still suggest unprotected Beat, Bass and Energy values.</p>`)}${section(notice('Already protected','Colour · Whole effect<br>Start and end · 0:00–0:24'))}`;}
function advancedResponse(){return `${section('<div class="eyebrow">Floating dust · Audio reaction</div><div class="row between"><h2>Advanced</h2><span class="tag">Custom</span></div>')}${section(`${slider('Beat',60,'beat')}${slider('Bass',20,'bass')}${slider('Energy',35,'energy')}${select('Changes',['Brightness','Emission','Size','Speed'],'Brightness','target')}${slider('Response limit',65,'limit')}${select('Smoothing',['Soft swells','Balanced','Sharp pulses'],'Soft swells','smoothing')}<p class="meta">Advanced edits make the response Custom. Appearance and fades stay as authored.</p>`)}${section(`<h3>Audio cues</h3><p class="small">Likely beat · 1:36.00</p><div class="row">${button('Add accent','accent')}${button('Edit cues','cues')}</div><p class="meta">Move a likely beat or add your own accent.</p>`)}`;}
function areaPanel(){return `${section('<div class="eyebrow">Floating dust</div><h2>Emitting area</h2><p class="meta">Whole composition · 0:00–3:12 · drag handles or enter percentages</p>')}${section(`${select('Coverage',['Full frame','Emitting area'],'Emitting area')}<div class="inline-form">${[['Left',10],['Top',69],['Width',80],['Height',23]].map(([label,value])=>field(label,`<span class="row"><input type="number" aria-label="Area ${label}" value="${value}" min="0" max="100"><span>%</span></span>`)).join('')}</div>${select('Direction',['Upwards','Downwards','Drift'],'Upwards')}${slider('Speed',18,'speed')}`)}${section(`<h3>Appearance</h3>${slider('Amount',42,'amount')}${slider('Opacity',60,'opacity')}<div class="row between"><span class="small">Colour</span><span class="row"><i class="swatch"></i>Warm ivory</span></div>`)}${section(`${button('Edit audio reaction','response')}${button('Ask Arke about this area','ask')}`)}`;}
function panel(o={}){if(o.panel==='placement')return placementPanel(o);if(o.panel==='sources')return sourcePanel();if(o.panel==='response')return response(o);if(o.panel==='advanced')return advancedResponse();if(o.panel==='area')return areaPanel();if(o.panel==='curves')return curvesPanel();if(o.panel==='chat')return conversation(o);if(o.panel==='changes')return conversation({...o,details:true});if(o.panel==='protect-audio')return audioProtectionPanel();if(o.panel==='protect')return protectPanel();if(o.stale)return section(notice('Timeline changed','An edit landed while this suggestion was pending. Your dust amount at 24% is retained.',true))+section(`<h2>Update before applying</h2><p class="small">Opening timing changed. Review the new arrangement against the current cut.</p>${button('Update review','update','primary')}${button('Return to current','current')}`);return appearance(o.applied?{...o,review:false}:o);}
function mobileSheet(o){let content=panel(o),title=o.panel==='response'?'Audio reaction':['chat','changes'].includes(o.panel)?'Arke':'Floating dust';if(o.sheet==='library'){content=`${presets()}${button('Add Floating dust','place','primary')} ${button('Suggest arrangement','suggest')}`;title='Effects';}return `<div class="sheet"><div class="sheet-head"><h2>${title}</h2>${button('Done','close-sheet')}</div><div class="sheet-scroll">${content}</div><div class="sheet-foot">${button(o.sheet==='library'?'Choose placement':'Back to timeline','close-sheet')}</div></div>`;}
